import json
import re
import sys

def parse_script(text):
    nodes = []
    edges = []

    # Split by blocks [NodeID]
    blocks = re.split(r'\n?\s*\[(.*?)\]\s*\n', '\n' + text.strip())
    if blocks[0] == '':
        blocks = blocks[1:]

    for i in range(0, len(blocks), 2):
        node_id = blocks[i]
        content = blocks[i+1].strip()

        lines = [l.strip() for l in content.split('\n') if l.strip()]

        node = {
            "id": node_id,
            "text": "",
            "speaker": "",
            "type": ""
        }

