        if lines and re.match(r'^\d+\.', lines[0]):
            node["type"] = "choice"
            for line in lines:
                match = re.match(r'^(\d+\..*?)\s*->\s*(.*)$', line)
                if match:
                    edge_text = match.group(1).strip()
                    target = match.group(2).strip()
                    edges.append({"from": node_id, "to": target, "text": edge_text})
