                # Case where there might not be a transition or different format
                match_no_trans = re.match(r'^(.*?):\s*(.*)$', lines[0])
                if match_no_trans:
                    node["speaker"] = match_no_trans.group(1).strip()
                    node["text"] = match_no_trans.group(2).strip()
        else:
            # Empty node (like End)
            node["type"] = "line"

        nodes.append(node)

    # Handle nodes that are targets but not defined in blocks (like End)
    existing_node_ids = {n["id"] for n in nodes}
    target_node_ids = {e["to"] for e in edges}
    for target_id in target_node_ids:
        if target_id not in existing_node_ids:
            nodes.append({
                "id": target_id,
                "text": "",
                "speaker": "",
                "type": "line"
            })

    return {"nodes": nodes, "edges": edges}

def main():
    try:
